import React, { useState } from "react";

const HoverPreviewLink = ({ href, children, previewSrc }) => {
  const [pos, setPos] = useState({ x: 0, y: 0 });
  const [visible, setVisible] = useState(false);

  const handleMouseMove = (e) => {
    setPos({ x: e.clientX, y: e.clientY });
  };

  return (
    <span
      onMouseEnter={() => setVisible(true)}
      onMouseLeave={() => setVisible(false)}
      onMouseMove={handleMouseMove}
      style={{ position: "relative" }}
    >
      <a href={href} style={{ textDecoration: "underline" }} target="_blank" rel="noopener noreferrer">
        {children}
      </a>

      {visible && (
        <img
          src={previewSrc}
          alt="preview"
          style={{
            position: "fixed", // follow viewport, not document flow
            top: pos.y + 20,   // offset from cursor
            left: pos.x + 20,
            width: "512px",
            height: "auto",
            pointerEvents: "none", // avoid blocking the link
            borderRadius: "8px",
            boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
            zIndex: 9999,
          }}
        />
      )}
    </span>
  );
};

export default HoverPreviewLink;